mapper.select:
SELECT clubOwner_key
FROM clubOwner
WHERE memberIdx = #{memberIdx}

mapper.insert:
INSERT INTO club ( clubOwner_key, club_name, club_region, club_content, club_created, club_status
, club_logo
) VALUES ( #{clubOwner_key}, #{club_name}, #{club_region}, #{club_content}, TO_DATE(#{club_created}, 'YYYY-MM-DD'), 1
, #{club_logo}
)

mapper.update:
UPDATE club
SET
	club_name = #{club_name},
	club_region = #{club_region},
	club_content = #{club_content}
	
		, club_created = TO_DATE(#{club_created}, 'YYYY-MM-DD')
	
	
		, club_logo = #{club_logo}
	
WHERE clubOwner_key = #{clubOwner_key}
